int lm_build_run_bootstrap(const char * trusted_make, const char * built_trans)
{
    char * output_dir;
    char parser_library[512];
    char own_library[512];
    output_dir = lm_build_output_dir();
    snprintf(parser_library, sizeof(parser_library), "%s/libparser.lm0.a", output_dir);
    snprintf(own_library, sizeof(own_library), "%s/libown.lm0.a", output_dir);
    if (lm_build_make(trusted_make, "mkdir", "\"lm1/build\" \"lm1/build/l1src\" \"build/obj\" \"build/lm0\" \"build/lm0/next\" \"build/lm0/next/check\"") != 0) {
    return 1;
    }
    if (lm_build_generate_all(built_trans) != 0) {
    return 1;
    }
    if (lm_build_parser_library(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_own_library(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_compile_l1trans(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_generate_all(built_trans) != 0) {
    return 1;
    }
    if (lm_build_parser_library(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_own_library(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_compile_l1trans(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_compile_generated_tools(trusted_make, output_dir) != 0) {
    return 1;
    }
    if (lm_build_opt_next != 0) {
    return 0;
    }
    if (lm_build_run_canary() != 0) {
    fprintf(stderr, "buildCore.lm0: staged bootstrap tools failed the --next rebuild; live tools were not overwritten\n");
    return 1;
    }
    fprintf(stderr, "buildCore.lm0: running staged tests (%s)\n", lm_build_test_suite_name(lm_build_opt_tests));
    if (lm_build_setenv("LM_TEST_SUITE", lm_build_test_suite_name(lm_build_opt_tests)) != 0) {
    fprintf(stderr, "buildCore.lm0: cannot set LM_TEST_SUITE\n");
    return 1;
    }
    if (lm_build_run_staged_tests(trusted_make, output_dir, parser_library, own_library) != 0) {
    fprintf(stderr, "buildCore.lm0: staged bootstrap tools failed tests; live tools were not overwritten\n");
    return 1;
    }
    if (lm_build_opt_full != 0) {
    if (lm_build_full_project() != 0) {
    return 1;
    }
    }
    return lm_build_defer_finalize();
}
int main(int argc, char ** argv)
{
    char * trusted_make;
    char trusted_make_buffer[128];
    char built_trans_buffer[128];
    int parse_status;
    parse_status = lm_build_parse_options(argc, argv);
    if (parse_status == 2) {
    return 0;
    }
    if (parse_status != 0) {
    return 1;
    }
    if (lm_build_enter_project_root(argv[0]) != 0) {
    return 1;
    }
    if (lm_build_thread_provider() == 0) {
    return 1;
    }
    snprintf(trusted_make_buffer, sizeof(trusted_make_buffer), "build%slm0%smake.lm0%s", lm_build_path_sep(), lm_build_path_sep(), lm_build_exe_suffix());
    snprintf(built_trans_buffer, sizeof(built_trans_buffer), "build%slm0%sl1trans.lm0%s", lm_build_path_sep(), lm_build_path_sep(), lm_build_exe_suffix());
    if (lm_build_opt_next != 0) {
    snprintf(trusted_make_buffer, sizeof(trusted_make_buffer), "build%slm0%snext%smake.lm0%s", lm_build_path_sep(), lm_build_path_sep(), lm_build_path_sep(), lm_build_exe_suffix());
    snprintf(built_trans_buffer, sizeof(built_trans_buffer), "build%slm0%snext%sl1trans.lm0%s", lm_build_path_sep(), lm_build_path_sep(), lm_build_path_sep(), lm_build_exe_suffix());
    }
    trusted_make = lm_build_env_or_default("LM_MAKE", trusted_make_buffer);
    return lm_build_run_bootstrap(trusted_make, built_trans_buffer);
}
